/* Document workbench: local SHA-256, explicit read-only checks, wallet hand-off. */
(() => {
  'use strict';
  const core=()=>globalThis.NodusDocumentCore;
  const t=(key,params)=>globalThis.NodusDocumentText?.(key,params)??key;
  const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const clone=value=>JSON.parse(JSON.stringify(value));
  const storageKey='nodus-observatory-document-settings-v1';
  const state={tab:'record',contract:'',publisher:'',digest:null,expectedDigest:null,expectedChain:null,fileName:'',fileSize:null,hashing:false,checking:false,result:null,error:null,referenceLoaded:false};
  let root=null,language=null,loaded=false,storageUnavailable=false,notice='',version=0,hashVersion=0,referenceVersion=0,controller=null,artifact=null,artifactController=null;
  const active=()=>globalThis.location?.hash==='#contracts';
  const currentLanguage=()=>globalThis.NodusI18n?.language?.()||'fi';
  const fail=code=>{const error=new Error(code);error.code=code;return error;};
  const errors={file_too_large:'Choose a file no larger than 64 MiB.',crypto_unavailable:'Secure hashing is unavailable. Open this page over HTTPS or localhost.',file_changed:'The file changed while being read. Select it again.',file:'The file could not be read. Select a local file.',hash_result:'Hashing failed. No document digest was retained.',file_limit:'The file limit is invalid.',address:'Enter nonzero Nodus EVM addresses: 0x and 64 hexadecimal characters.',digest:'Select a document to calculate its SHA-256 digest.',reference:'The reference file is invalid. Import an unmodified document reference JSON.',reference_size:'Choose a reference JSON no larger than 16 KiB.',reference_mismatch:'This file does not match the imported reference. Select the original file or clear the reference.',query:'The node could not check this record. No verification result is available.',response:'The node returned an invalid or mismatched response. No verification result is available.',timeout:'The record check timed out. Try again.',artifact:'The bundled compiler artifacts failed verification. Downloads were blocked.',copy:'Copy failed. Select and copy the displayed value instead.',backend_invalid_query:'The public query parameters were rejected. Check the selected addresses and document.',backend_stale_chain_context:'A fresh synchronized node measurement is required. Wait for the collector to refresh, then retry.',backend_chain_mismatch:'The reference expects a different network. Select the correct Nodus network or clear the reference.',backend_busy:'Document checks are busy. Wait a moment and retry.',backend_node_unavailable:'The local node did not complete the read-only check. Check its service and CLI version, then retry.',backend_invalid_node_response:'The local node returned an unsupported or inconsistent registry response. Check the selected contract and node version.'};
  function errorText(code){return t(errors[code]||errors.query);}
  function button(label,action,disabled=false,primary=false){return `<button type="button" class="document-button${primary?' primary':''}" data-document-action="${action}"${disabled?' disabled':''}>${esc(t(label))}</button>`;}
  function invalidate(){version++;controller?.abort();controller=null;artifactController?.abort();artifactController=null;state.checking=false;state.result=null;state.error=null;notice='';}
  function saveSettings(){try{localStorage.setItem(storageKey,JSON.stringify({contract:state.contract,publisher:state.publisher}));}catch{storageUnavailable=true;}}
  function loadSettings(){if(loaded)return;loaded=true;try{const value=localStorage.getItem(storageKey);if(!value)return;const parsed=JSON.parse(value);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed)||Object.keys(parsed).some(key=>!['contract','publisher'].includes(key)))return;for(const key of ['contract','publisher'])if(typeof parsed[key]==='string'&&parsed[key].length<=66)state[key]=parsed[key];}catch{storageUnavailable=true;}}
  function parameters(){try{if(!state.digest||state.hashing)throw fail('digest');return {contract:core().normalizeAddress(state.contract.trim()),publisher:core().normalizeAddress(state.publisher.trim()),digest:core().normalizeDigest(state.digest)};}catch{return null;}}
  const mismatch=()=>Boolean(state.expectedDigest&&state.digest&&state.expectedDigest!==state.digest);
  const ready=()=>Boolean(parameters()&&!mismatch());
  function render(){
    if(!root||!active())return;
    if(!core()){root.innerHTML=`<section class="document-workbench"><h1>${esc(t('Document registry'))}</h1><p>${esc(t('Document tools are unavailable. Reload after installing all assets.'))}</p></section>`;return;}
    root.innerHTML=`<div class="document-workbench" id="document-notary">
      <header class="document-hero"><div><span class="eyebrow">${esc(t('CONTRACT STUDIO / DOCUMENTS'))}</span><h1>${esc(t('Keep the file. Anchor its fingerprint.'))}</h1><p>${esc(t('Record a document’s SHA-256 digest in Nodus. Later, check whether the exact same bytes have a record under a selected publisher.'))}</p></div><span class="document-seal" aria-hidden="true">#</span></header>
      <nav class="document-catalog" aria-label="${esc(t('Contract examples'))}"><a href="#contracts" aria-current="page"><strong>${esc(t('Document registry'))}</strong><span>${esc(t('Hash · register · check'))}</span></a><a href="#contracts-escrow"><strong>${esc(t('Escrow example'))} ↗</strong><span>${esc(t('Explore the earlier payment contract'))}</span></a></nav>
      <div class="document-trust"><strong>${esc(t('Your document stays on this device.'))}</strong><p>${esc(t('Only an explicit record check sends its digest and the selected public addresses to this server. Signing stays in the Nodus wallet. No file upload, private keys or automatic transactions.'))}</p></div>
      <div class="document-tabs" role="tablist" aria-label="${esc(t('Document workflow'))}">${[['record','Record a document'],['verify','Check a document'],['registry','Set up a registry']].map(([tab,label])=>`<button type="button" id="document-tab-${tab}" role="tab" data-document-tab="${tab}" aria-selected="${state.tab===tab}" tabindex="${state.tab===tab?0:-1}">${esc(t(label))}</button>`).join('')}</div>
      <section class="document-context document-card"><div class="document-section-head"><span class="eyebrow">${esc(t('SELECTED REGISTRY'))}</span><span class="document-local">${esc(t(storageUnavailable?'Settings are session-only':'Only public address settings are saved'))}</span></div><div class="document-fields"><label for="document-contract">${esc(t('Registry contract address'))}<input id="document-contract" type="text" value="${esc(state.contract)}" placeholder="0x…" spellcheck="false" autocomplete="off"><small>${esc(t('The deployed document registry contract, not a wallet address.'))}</small></label><label for="document-publisher">${esc(t('Publisher EVM address'))}<input id="document-publisher" type="text" value="${esc(state.publisher)}" placeholder="0x…" spellcheck="false" autocomplete="off"><small>${esc(t('The wallet that registers or registered this digest. 0x + 64 hexadecimal characters.'))}</small></label></div></section>
      <section class="document-tab-panel" role="tabpanel" aria-labelledby="document-tab-${state.tab}">${state.tab==='registry'?registryPanel():`${filePanel()}<div class="document-main-grid"><section class="document-card document-steps">${state.tab==='record'?recordPanel():verifyPanel()}</section><aside class="document-card document-explain"><span class="eyebrow">${esc(t('WHAT THIS PROVES'))}</span><h2>${esc(t('Same bytes. A recorded claim.'))}</h2><p>${esc(t('A matching SHA-256 digest links the selected file to a registry record. The record identifies a publisher address and its recorded block time.'))}</p><p>${esc(t('It does not prove who controls that address, who authored the document or whether its contents are true. Trust the registry and publisher separately.'))}</p><p>${esc(t('A visually identical PDF, a resaved document or a scan can have different bytes and a different digest. Keep the original file.'))}</p><div class="document-fact"><span>SHA-256</span><strong>${esc(t('Calculated locally'))}</strong></div><div class="document-fact"><span>${esc(t('Document upload'))}</span><strong>${esc(t('None'))}</strong></div><div class="document-fact"><span>${esc(t('Verification source'))}</span><strong>${esc(t('Your local Nodus node'))}</strong></div></aside></div>`}</section>
      <section id="document-result" aria-live="polite">${resultPanel()}</section><p class="document-notice" id="document-notice" role="status">${esc(notice?t(notice):'')}</p>
      <input type="file" id="document-reference" accept="application/json,.json" hidden>
    </div>`;
    language=currentLanguage();bind();updateControls();
  }
  function filePanel(){return `<section class="document-card document-file-card"><div id="document-dropzone" class="document-dropzone${state.hashing?' hashing':''}"><span class="document-file-symbol" aria-hidden="true">▤</span><div><h2>${esc(t(state.hashing?'Calculating SHA-256…':'Choose the document'))}</h2><p>${esc(t('Drop a file here or choose one. Up to 64 MiB. Its contents are read only in your browser.'))}</p><div class="document-file-actions">${button('Choose file','choose-file')}<input id="document-file" type="file" hidden><span class="document-file-name">${esc(state.fileName||t('No file selected'))}${state.fileSize!==null?` · ${esc(formatBytes(state.fileSize))}`:''}</span></div></div></div><label class="document-digest-label" for="document-digest">${esc(t('Document digest · SHA-256'))}</label><textarea id="document-digest" readonly rows="2" spellcheck="false">${esc(state.digest||'')}</textarea><div class="document-small-actions">${button('Copy digest','copy-digest',!state.digest)}<span>${esc(t('The filename is not part of the digest. The file contents are.'))}</span></div><div id="document-reference-state">${referencePanel()}</div></section>`;}
  function referencePanel(){if(!state.referenceLoaded)return '';return `<div class="document-reference ${mismatch()?'mismatch':''}"><strong>${esc(t(mismatch()?'File differs from the imported reference':state.digest?'File digest matches the reference — check the node next':'Reference loaded — select the original file'))}</strong><p>${esc(t('A reference JSON is user-supplied data. Its saved claims are not verification results.'))}</p><code>${esc(state.expectedDigest)}</code>${state.expectedChain?`<p>${esc(t('Expected chain'))}: <code>${esc(state.expectedChain)}</code></p>`:''}${button('Clear reference','clear-reference')}</div>`;}
  function recordPanel(){return `<span class="eyebrow">${esc(t('WALLET HAND-OFF'))}</span><h2>${esc(t('Register the fingerprint, not the file.'))}</h2><ol class="document-workflow"><li><strong>${esc(t('Choose a document and the two public addresses above.'))}</strong><p>${esc(t('If you have no registry contract yet, use Set up a registry first.'))}</p></li><li><strong>${esc(t('Open the registry in the official wallet.'))}</strong><p>${esc(t('Load the downloaded ABI for the selected contract. Choose register(bytes32), paste the digest and send value 0. Sign with the publisher wallet; native funds are needed for fees.'))}</p><div class="document-small-actions">${button('Copy register calldata','copy-register',!ready())}<a class="document-button" href="https://wallet.nodusnetwork.io/#contracts" target="_blank" rel="noopener noreferrer">${esc(t('Open Nodus wallet'))} ↗</a></div><details><summary>${esc(t('Show register calldata'))}</summary><code class="document-code">${esc(state.digest?core().encodeRegister(state.digest):t('Select a document first.'))}</code></details></li><li><strong>${esc(t('Wait for confirmation, then check the record.'))}</strong><p>${esc(t('Copying data or opening the wallet does not register anything. Only a fresh node check can display a record here.'))}</p>${button('Check record now','check-record',!ready()||state.checking,true)}</li></ol><div class="document-small-actions">${button('Download reference JSON','export-reference',!ready())}${button('Import reference JSON','import-reference')}</div>`;}
  function verifyPanel(){return `<span class="eyebrow">${esc(t('EXPLICIT READ-ONLY CHECK'))}</span><h2>${esc(t('Compare this file with the selected registry.'))}</h2><p>${esc(t('Select the original file and enter the registry and publisher addresses, or import a reference JSON to fill those addresses. Then request a fresh read from the node.'))}</p><div class="document-verify-actions">${button(state.checking?'Checking…':'Check record now','check-record',!ready()||state.checking,true)}${button('Import reference JSON','import-reference')}${button('Download reference JSON','export-reference',!ready())}</div><p>${esc(t('Not found means no entry for this publisher, registry and digest. It is not proof that nobody registered the document elsewhere.'))}</p><details class="document-revoke"><summary>${esc(t('Publisher controls: revoke a record'))}</summary><p>${esc(t('Only the original publisher can revoke its record. Revocation is permanent; it leaves the original block and timestamp visible. This button only copies calldata, it does not send a transaction.'))}</p>${button('Copy revoke calldata','copy-revoke',!ready())}<code class="document-code">${esc(state.digest?core().encodeRevoke(state.digest):t('Select a document first.'))}</code></details>`;}
  function registryPanel(){return `<section class="document-card document-registry"><span class="eyebrow">${esc(t('ONE-TIME CONTRACT DEPLOYMENT'))}</span><h2>${esc(t('A registry that keeps the original record.'))}</h2><p>${esc(t('Deploy this contract once, then use its address for many documents. Each publisher records its own SHA-256 digests. An existing entry cannot be overwritten, and revocation cannot be undone.'))}</p><div class="document-artifact-actions">${button('Download ABI','download-abi',false,true)}${button('Download creation bytecode','download-bytecode')}${button('Download Solidity source','download-source')}<a class="document-button" href="https://wallet.nodusnetwork.io/#contracts" target="_blank" rel="noopener noreferrer">${esc(t('Open Nodus wallet'))} ↗</a></div><ol class="document-workflow"><li>${esc(t('Download the ABI and creation bytecode. They are checked against pinned hashes of the Nodus address256 compiler build before download.'))}</li><li>${esc(t('In the wallet’s contract deployment screen, supply the ABI and creation bytecode. There are no constructor arguments. Use value 0 and sign with your wallet; native funds are needed for fees.'))}</li><li>${esc(t('After confirmation, copy the deployed contract address into Registry contract address above. Select the publisher wallet’s EVM address when recording documents.'))}</li></ol><div class="document-compiler"><strong>Nodus solc 0.8.30 · address256</strong><span>${esc(t('Source SHA-256'))}</span><code>${esc(core().SOURCE_SHA256)}</code><span>${esc(t('Runtime SHA-256'))}</span><code>${esc(core().RUNTIME_SHA256)}</code></div><details><summary>${esc(t('Inspect the Solidity source'))}</summary><pre class="document-source"><code>${esc(core().SOURCE)}</code></pre></details><p>${esc(t('Artifact hashes identify these downloaded files. This page does not verify that a selected on-chain contract runs this bytecode.'))}</p></section>`;}
  function formatBytes(size){return size<1024?`${size} B`:size<1048576?`${(size/1024).toFixed(1)} KiB`:`${(size/1048576).toFixed(1)} MiB`;}
  function timeLabel(value){try{const n=BigInt(value);if(n>8640000000000n)return t('Outside supported calendar range');return new Date(Number(n)*1000).toISOString().replace('.000Z','Z');}catch{return '—';}}
  function resultPanel(){if(state.error)return `<div class="document-result error"><strong>${esc(t('No verified result'))}</strong><p>${esc(errorText(state.error))}</p></div>`;if(state.checking)return `<div class="document-result pending"><strong>${esc(t('Reading the selected registry…'))}</strong></div>`;if(!state.result)return '';const value=state.result;return `<div class="document-result ${value.status==='registered'?'registered':value.status==='revoked'?'revoked':'missing'}"><span class="eyebrow">${esc(t('NODE-REPORTED RESULT'))}</span><h2>${esc(t(value.status==='registered'?'File matches a record in the selected registry':value.status==='revoked'?'Matching record has been revoked':'No record found for this publisher and registry'))}</h2><p>${esc(t('This result is reported by your local node. It is not an independent on-chain inclusion proof, and the selected contract’s code has not been verified.'))}</p><dl>${[['Publisher',value.publisher],['Registry',value.contract],['Document digest',value.digest],['Chain ID',value.chain.chain_id],['Record block',value.record.block_number??'—'],['Record time · UTC',value.record.timestamp!==null?timeLabel(value.record.timestamp):'—'],['Node query height',value.chain.height],['Collector snapshot height',value.chain.snapshot_height],['Checked at',value.checked_at]].map(([label,content])=>`<div><dt>${esc(t(label))}</dt><dd>${esc(content)}</dd></div>`).join('')}</dl><p>${esc(t('The record time is a chain-reported block timestamp, not a document creation date or a guaranteed civil-time timestamp. The chain ID is from the local collector snapshot, not independently verified.'))}</p>${value.status==='revoked'?`<p><strong>${esc(t('The publisher has withdrawn this record. The historical entry remains.'))}</strong></p>`:''}</div>`;}
  function updateControls(){if(!root||!active())return;root.querySelectorAll('[data-document-action]').forEach(element=>{const action=element.dataset.documentAction;if(['check-record','copy-register','copy-revoke','export-reference'].includes(action))element.disabled=!ready()||(action==='check-record'&&state.checking);else if(action==='copy-digest')element.disabled=!state.digest;});const result=root.querySelector('#document-result');if(result)result.innerHTML=resultPanel();const reference=root.querySelector('#document-reference-state');if(reference)reference.innerHTML=referencePanel();const message=root.querySelector('#document-notice');if(message)message.textContent=notice?t(notice):'';root.querySelectorAll('[data-document-action="clear-reference"]').forEach(element=>element.onclick=()=>act('clear-reference'));}
  async function chooseFile(file){invalidate();const token=++hashVersion;state.digest=null;state.fileName=typeof file?.name==='string'?file.name:'';state.fileSize=Number.isSafeInteger(file?.size)?file.size:null;state.hashing=true;render();try{const digest=await core().hashFile(file);if(token!==hashVersion||!active())return;state.digest=digest;state.hashing=false;if(mismatch())state.error='reference_mismatch';render();}catch(error){if(token!==hashVersion||!active())return;state.digest=null;state.hashing=false;state.error=errors[error.code]?error.code:'file';render();}}
  const uint=value=>typeof value==='string'&&/^(0|[1-9][0-9]{0,77})(?![\s\S])/.test(value)&&BigInt(value)<(1n<<256n);
  const positiveU64=value=>uint(value)&&BigInt(value)>0n&&BigInt(value)<(1n<<64n);
  const validUTC=value=>typeof value==='string'&&/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|\+00:00)(?![\s\S])/.test(value)&&Number.isFinite(Date.parse(value))&&new Date(value).toISOString().slice(0,19)===value.slice(0,19);
  const plain=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
  function validateResponse(value,request){
    if(!plain(value)||value.available!==true||!['registered','revoked','not_found'].includes(value.status))throw fail('response');
    for(const field of ['contract','publisher','digest'])if(typeof value[field]!=='string'||value[field]!==request[field])throw fail('response');
    const record=value.record,chain=value.chain,p=value.provenance;
    if(!plain(record)||typeof record.exists!=='boolean'||typeof record.revoked!=='boolean'||!plain(chain)||!plain(p))throw fail('response');
    if(typeof chain.chain_id!=='string'||!/^[0-9a-f]{64}(?![\s\S])/.test(chain.chain_id)||!positiveU64(chain.height)||!positiveU64(chain.snapshot_height)||BigInt(chain.height)<BigInt(chain.snapshot_height)||chain.chain_id_source!=='local_collector_snapshot'||chain.chain_id_verified!==false)throw fail('response');
    if(request.chain&&chain.chain_id!==request.chain)throw fail('response');
    if(p.source!=='local_node'||p.endpoint!=='127.0.0.1:4001'||p.independent_verification!==false||p.contract_code_verified!==false)throw fail('response');
    if(!validUTC(value.checked_at))throw fail('response');
    if(value.status==='not_found'){if(record.exists!==false||record.revoked!==false||record.block_number!==null||record.timestamp!==null)throw fail('response');}
    else if(record.exists!==true||record.revoked!==(value.status==='revoked')||!positiveU64(record.block_number)||!positiveU64(record.timestamp)||BigInt(record.block_number)>BigInt(chain.height))throw fail('response');
    return clone(value);
  }
  async function backendError(response){
    let value;
    try{
      if(response.body?.getReader){
        const reader=response.body.getReader(),decoder=new TextDecoder();let text='',length=0;
        try{while(true){const part=await reader.read();if(part.done)break;length+=part.value?.byteLength||0;if(length>4096){await reader.cancel();return 'query';}text+=decoder.decode(part.value,{stream:true});}text+=decoder.decode();}finally{reader.releaseLock?.();}
        value=JSON.parse(text);
      }else if(typeof response.text==='function'){const text=await response.text();if(new TextEncoder().encode(text).byteLength>4096)return 'query';value=JSON.parse(text);}
      else{value=await response.json();if(JSON.stringify(value).length>4096)return 'query';}
      const allowed=['invalid_query','stale_chain_context','chain_mismatch','busy','node_unavailable','invalid_node_response'];
      if(value?.available===false&&value.status==='unavailable'&&allowed.includes(value.error?.code))return `backend_${value.error.code}`;
    }catch{}
    return 'query';
  }
  async function checkRecord(){if(!ready())return;invalidate();state.checking=true;const token=version,request={...parameters(),chain:state.expectedChain};controller=new AbortController();const currentController=controller;let timedOut=false;const timer=setTimeout(()=>{timedOut=true;currentController.abort();},20000);render();try{const query=new URLSearchParams({contract:request.contract,publisher:request.publisher,digest:request.digest});if(request.chain)query.set('chain',request.chain);const response=await fetch(`/api/documents/record?${query}`,{method:'GET',signal:currentController.signal,cache:'no-store',headers:{Accept:'application/json'}});if(!response.ok)throw fail(await backendError(response));const result=validateResponse(await response.json(),request);if(timedOut)throw fail('timeout');if(token!==version||!active())return;state.result=result;state.checking=false;state.error=null;render();}catch(error){if(token!==version||!active())return;state.result=null;state.checking=false;state.error=timedOut?'timeout':errors[error.code]?error.code:'query';render();}finally{clearTimeout(timer);if(controller===currentController)controller=null;}}
  function download(text,name,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=name;document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function copy(value){try{await navigator.clipboard.writeText(value);if(active()){notice='Copied to clipboard.';updateControls();}}catch{if(active()){state.error='copy';updateControls();}}}
  async function sha(bytes){if(!globalThis.crypto?.subtle)throw fail('artifact');const hash=new Uint8Array(await crypto.subtle.digest('SHA-256',bytes));return Array.from(hash,b=>b.toString(16).padStart(2,'0')).join('');}
  const hexBytes=hex=>Uint8Array.from(hex.slice(2).match(/../g)||[],part=>parseInt(part,16));
  async function verifiedArtifact(){if(artifact)return artifact;artifactController?.abort();const requestController=new AbortController();artifactController=requestController;const timer=setTimeout(()=>requestController.abort(),20000);try{const response=await fetch('/document-registry.json',{method:'GET',cache:'no-store',signal:requestController.signal});if(!response.ok)throw fail('artifact');const data=await response.json();if(!plain(data)||data.schema!=='nodus-document-registry-artifact/v1'||data.contractName!=='ObservatoryDocuments'||data.compiler?.version!=='0.8.30+nodus.addr256.commit.73712a01.Linux.g++'||data.compiler?.binarySha256!=='6c981f36ee790a46fa2310c4eb925e35909b020a58a19654a063517947ceffb4'||data.sourceSha256!==core().SOURCE_SHA256||data.runtimeSha256!==core().RUNTIME_SHA256||JSON.stringify(data.abi)!==JSON.stringify(core().ABI))throw fail('artifact');for(const field of ['creationBytecode','runtimeBytecode'])if(typeof data[field]!=='string'||!/^0x(?:[0-9a-fA-F]{2})+(?![\s\S])/.test(data[field])||data[field].length>100000)throw fail('artifact');const hashes=await Promise.all([sha(new TextEncoder().encode(core().SOURCE)),sha(hexBytes(data.creationBytecode)),sha(hexBytes(data.runtimeBytecode))]);if(hashes[0]!==core().SOURCE_SHA256||hashes[1]!==core().CREATION_SHA256||hashes[2]!==core().RUNTIME_SHA256)throw fail('artifact');if(requestController.signal.aborted)throw fail('artifact');artifact=data;return data;}finally{clearTimeout(timer);if(artifactController===requestController)artifactController=null;}}
  async function importReference(file){const token=++referenceVersion;invalidate();if(!file||!Number.isSafeInteger(file.size)||file.size<0||file.size>core().MAX_PROOF_LENGTH||typeof file.text!=='function'){state.error='reference_size';render();return;}try{const reference=core().parseProof(await file.text());if(token!==referenceVersion||!active())return;invalidate();state.contract=reference.registryAddress;state.publisher=reference.publisher;state.expectedDigest=reference.digest;state.expectedChain=reference.networkGenesisPin;state.referenceLoaded=true;state.tab='verify';state.result=null;state.error=mismatch()?'reference_mismatch':null;saveSettings();render();}catch{if(token!==referenceVersion||!active())return;state.error='reference';render();}}
  async function act(action){
    if(action==='choose-file'){root.querySelector('#document-file')?.click();return;}
    if(action==='import-reference'){root.querySelector('#document-reference')?.click();return;}
    if(action==='clear-reference'){referenceVersion++;invalidate();state.referenceLoaded=false;state.expectedDigest=null;state.expectedChain=null;render();return;}
    if(action==='check-record'){await checkRecord();return;}
    if(action==='copy-digest'&&state.digest){await copy(state.digest);return;}
    if(['copy-register','copy-revoke','export-reference'].includes(action)&&!ready())return;
    if(action==='copy-register'){await copy(core().encodeRegister(state.digest));return;}
    if(action==='copy-revoke'){await copy(core().encodeRevoke(state.digest));return;}
    if(action==='export-reference'){const params=parameters(),result=state.result;const proof=core().createProof({digest:params.digest,registryAddress:params.contract,publisher:params.publisher,networkGenesisPin:result?.chain.chain_id||state.expectedChain||null,claim:result?.record.exists?{blockNumber:result.record.block_number,timestamp:result.record.timestamp,revoked:result.record.revoked}:null});download(JSON.stringify(proof,null,2)+'\n','nodus-document-reference.json','application/json');notice='Reference exported. Its claims require a fresh node check.';updateControls();return;}
    if(['download-source','download-abi','download-bytecode'].includes(action)){const token=version;try{if(action==='download-source'){if(await sha(new TextEncoder().encode(core().SOURCE))!==core().SOURCE_SHA256)throw fail('artifact');if(token===version&&active())download(core().SOURCE,'ObservatoryDocuments.sol','text/plain');}else{const data=await verifiedArtifact();if(token!==version||!active())return;if(action==='download-abi')download(JSON.stringify(data.abi,null,2)+'\n','ObservatoryDocuments.abi.json','application/json');else download(data.creationBytecode+'\n','ObservatoryDocuments.creation.hex','text/plain');}if(token===version&&active()){notice='Download ready. Review it in the official wallet.';updateControls();}}catch{if(token===version&&active()){state.error='artifact';updateControls();}}}
  }
  function bind(){
    root.querySelectorAll('[data-document-action]').forEach(element=>element.onclick=()=>act(element.dataset.documentAction));
    root.querySelectorAll('[data-document-tab]').forEach(element=>{element.onclick=()=>{state.tab=element.dataset.documentTab;render();root.querySelector(`#document-tab-${state.tab}`)?.focus();};element.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=['record','verify','registry'],index=tabs.indexOf(state.tab);state.tab=event.key==='Home'?'record':event.key==='End'?'registry':tabs[(index+(event.key==='ArrowRight'?1:2))%3];render();root.querySelector(`#document-tab-${state.tab}`)?.focus();};});
    for(const key of ['contract','publisher']){const input=root.querySelector(`#document-${key}`);if(input)input.oninput=input.onchange=()=>{referenceVersion++;invalidate();state[key]=input.value;saveSettings();updateControls();};}
    const file=root.querySelector('#document-file');if(file)file.onchange=()=>chooseFile(file.files?.[0]);
    const reference=root.querySelector('#document-reference');if(reference)reference.onchange=()=>importReference(reference.files?.[0]);
    const zone=root.querySelector('#document-dropzone');if(zone){zone.ondragover=event=>{event.preventDefault();zone.classList.add('dragging');};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=event=>{event.preventDefault();zone.classList.remove('dragging');return chooseFile(event.dataTransfer.files?.[0]);};}
  }
  globalThis.NodusDocumentNotary=Object.freeze({mount(target){const same=root===target&&target?.querySelector?.('#document-notary');root=target;loadSettings();if(!same||language!==currentLanguage())render();},getState:()=>clone(state)});
  globalThis.addEventListener?.('hashchange',()=>{if(!active()){invalidate();hashVersion++;referenceVersion++;state.hashing=false;}});
})();
